INSERT INTO feature VALUES('sharing-inventory','workflow','Every sharing site rowed under its descent datum',NULL,'implemented','ordinary',NULL,'`ledger/concerns.sql` rows each module where work wanted at several positions is done once and read at each, under the descent datum it fits: its positions, cover, compatibility and gluing, and the certificate the kernel replays or why there is none. `check:purposes` refuses an entry tagged with a concern that no site of that concern covers, and `check:crate-map` a site naming a module its crate lacks.',NULL,'.config/purposes/coverage.json ledger/concerns.sql',NULL,NULL);
